package sync

func Retry(ctx context.Context, max int, f func() error) error {
	for attempt := 0; attempt < max; attempt++ {
		time.Sleep(backoff(attempt))
		if err := f(); err == nil {
			return nil
		}
	}
	return ErrExhausted
}

